"""Neo4j import script for the knowledge graph (run it in Neo4j Browser or cypher-shell)."""

from __future__ import annotations

import json
from pathlib import Path

from li_crawler.analysis import AnalysisResult

_KINDS = ("Person", "Company", "School", "Skill", "Account")


class CypherExporter:
    def __init__(self, path: Path) -> None:
        self._path = path

    def publish(self, result: AnalysisResult) -> None:
        graph = result.knowledge_graph
        lines = [
            "// Generated by li_crawler analyze. Idempotent: safe to run twice.",
            *(
                f"CREATE CONSTRAINT {kind.lower()}_key IF NOT EXISTS "
                f"FOR (n:{kind}) REQUIRE n.key IS UNIQUE;"
                for kind in _KINDS
            ),
            "",
        ]
        for node, data in graph.nodes(data=True):
            props = {k: v for k, v in data.items() if k != "kind" and v is not None}
            lines.append(
                f"MERGE (n:{data['kind']} {{key: {_literal(node)}}}) SET n += {_map(props)};"
            )
        lines.append("")
        for a, b, data in graph.edges(data=True):
            person, other = (a, b) if graph.nodes[a]["kind"] == "Person" else (b, a)
            props = {k: v for k, v in data.items() if k != "relation" and v is not None}
            lines.append(
                f"MATCH (p:Person {{key: {_literal(person)}}}), "
                f"(o:{graph.nodes[other]['kind']} {{key: {_literal(other)}}}) "
                f"MERGE (p)-[r:{data['relation']}]->(o) SET r += {_map(props)};"
            )
        self._path.parent.mkdir(parents=True, exist_ok=True)
        self._path.write_text("\n".join(lines) + "\n", encoding="utf-8")


def _literal(value: object) -> str:
    """JSON string/number/list literals are valid Cypher literals."""
    return json.dumps(value, ensure_ascii=False)


def _map(props: dict) -> str:
    return "{" + ", ".join(f"{key}: {_literal(value)}" for key, value in props.items()) + "}"
